/**
 * How wide each character of the system font is drawn, as Chrome measures it with the font the
 * device draws in: San Francisco on iOS (and in Chrome on a Mac), Roboto on Android. Generated by
 * measuring every character at 16px in four weights (six for Roboto, which has 800 and 900), the tracking San Francisco adds at each size,
 * and the kerning pairs of 0.025em or more (for Roboto, every pair of 0.0015em or more, at 400).
 *
 * Each width is in thousandths of an em, in the order of `chars`; a size's tracking is added to
 * every character, and a pair's kerning between the two.
 */
export interface FontMetrics {
  readonly chars: string;
  readonly weights: Readonly<Record<400 | 700, readonly number[]>> &
    Readonly<Partial<Record<500 | 600 | 800 | 900, readonly number[]>>>;
  readonly sizes: readonly number[];
  readonly tracking: readonly number[];
  /** `AT-98 AV-78`: two characters and how much nearer they are, in thousandths of an em. */
  readonly kerning: string;
  /** The pairs of its bold, where they are not the same: 600 and heavier are kerned by these. */
  readonly boldKerning?: string;
  /**
   * How far a line reaches over its baseline and under it, and where its middle is, in ems. A
   * browser rounds the first two to whole pixels at the size it draws.
   */
  readonly ascent: number;
  readonly descent: number;
  readonly middle: number;
}

